import{bV as s,aL as n,u as e,G as p}from"./chunks/framework.C8THFwVE.js";const u=JSON.parse('{"title":"如何运营一段稳定的关系","description":"","frontmatter":{"date":"2026-04-01T05:16:24.000Z","title":"如何运营一段稳定的关系","permalink":"/heart/d646c0","categories":["心语角落"]},"headers":[],"relativePath":"19.心语角落/05.如何运营一段稳定的关系.md","filePath":"19.心语角落/05.如何运营一段稳定的关系.md"}'),l={name:"19.心语角落/05.如何运营一段稳定的关系.md"};function r(i,a,t,o,c,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="如何运营一段稳定的关系" tabindex="-1">如何运营一段稳定的关系 <a class="header-anchor" href="#如何运营一段稳定的关系" aria-label="Permalink to &quot;如何运营一段稳定的关系&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>回顾了一下自己跟别人的人际交往，发现自己其实并不善于经营一段稳定的关系，具体表现就是有事才去找别人，就事论事，讨论完事情立刻撤退，没有任何寒暄和缓冲，而且还有一个重要表现，就是不是在进攻，就是在撤退，不知道怎么稳定发展</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><h3 id="目标导向" tabindex="-1">目标导向 <a class="header-anchor" href="#目标导向" aria-label="Permalink to &quot;目标导向&quot;">​</a></h3><p>一种“目标导向”的思维惯性</p><p>在潜意识里，会把人际关系分成了几个阶段：陌生、认识、熟悉、亲密...，每个阶段都被当成了一个关卡，带着攻克关卡的目的去交流，自然就是发现了攻克的机会，就会进攻，没有机会，就会撤退</p><h3 id="解决问题" tabindex="-1">解决问题 <a class="header-anchor" href="#解决问题" aria-label="Permalink to &quot;解决问题&quot;">​</a></h3><p>习惯用“解决问题”的思维去对待关系</p><p>平时不联系，是因为没有具体的事要说，联系了，往往又是为了达成某个目的</p><p><strong>本质是没有把“分享”当成本身，当做一件重要的事</strong></p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>是什么导致了我这两种思维惯性？</p><details class="details custom-block"><summary>突然想起童年时候的一些经历</summary><p>放学到家后想要出去玩，就必须先把作业写完；想要一个玩具就必须学习成绩好；想要得到父母的夸奖与关注，就必须乖乖听话。</p><p>好似我想要某样东西，就必须得付出某种代价，或者达到某个要求，才能得到。</p><p>这种模式我查了一下，在心理学上叫做“有条件的爱”</p></details><h5 id="有条件的爱" tabindex="-1">有条件的爱 <a class="header-anchor" href="#有条件的爱" aria-label="Permalink to &quot;有条件的爱&quot;">​</a></h5><p>你感受到的爱、认可、甚至基本需求的满足，不是因为你“是谁”，而是因为你“做了什么”。</p><p>这种环境下长大的孩子，会形成一套根深蒂固的内心公式：</p><p><strong>“我必须先付出/达成/证明，才值得被爱。”</strong></p><h2 id="会怎样" tabindex="-1">会怎样 <a class="header-anchor" href="#会怎样" aria-label="Permalink to &quot;会怎样&quot;">​</a></h2><p>从小这样长大的人，会是怎样的人？</p><ol><li><strong>目标导向，过程无感</strong>：很难享受过程本身，关注点永远都在它能不能达成我的目标</li><li><strong>过度责任与讨好倾向</strong>：习惯性的认为关系的维持是我的责任，想要维持好关系，想要对方开心</li><li><strong>难以接受“无条件的给予”</strong>：很难安心的接受别人对你的好，很难相信别人会毫无缘由的对你好，始终认为天下没有免费的午餐。当别人对你好、接近你时，会感到不安</li><li><strong>对“拒绝”极度敏感</strong>：因为从小的经验告诉你：一旦没有达到标准，爱就会被收回。所以成年后，任何微小的拒绝，都能被放大成“我不够好”、“都是我的问题”。</li></ol><details class="details custom-block"><summary>TMD</summary><p>他妈的好真实，😂全中了</p></details><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><details class="details custom-block"><summary>这是一条根上长出的两个分支</summary><p>一条根：有条件的爱</p><p>两个分支：目标导向、解决问题</p></details><p>小时候必须靠表现来换取爱，是因为没有选择</p><p>而长大后，这种模式已经过时了，成年人的正常的人际关系，恰恰应该建立在“无条件”的基础上 —— 不是无条件的纵容，而是一种<b>“即使什么也不做，我人在这里就已经足够重要了”</b></p><p>所以这里我给出一种三层结构的解决方案：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        顶层 · 思维转变                       │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  从“我必须赚取爱”到“我本身就有资格被爱”                 │  │</span></span>
<span class="line"><span>│  │  从“关系是任务清单”到“关系是共同土壤”                   │  │</span></span>
<span class="line"><span>│  └───────────────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                      中间层 · 认知习惯                       │</span></span>
<span class="line"><span>│  ┌─────────────────────────┐  ┌──────────────────────────┐  │</span></span>
<span class="line"><span>│  │       习惯一            │  │         习惯二            │  │</span></span>
<span class="line"><span>│  │  区分“事实”与“旧程序”    │  │  把“撤退”转化为“留白”     │  │</span></span>
<span class="line"><span>│  └─────────────────────────┘  └──────────────────────────┘  │</span></span>
<span class="line"><span>│  ┌─────────────────────────┐  ┌──────────────────────────┐  │</span></span>
<span class="line"><span>│  │       习惯三            │  │         习惯四            │  │</span></span>
<span class="line"><span>│  │  接受“无目的的给予”      │  │  用“渐进”替代“进攻”       │  │</span></span>
<span class="line"><span>│  └─────────────────────────┘  └──────────────────────────┘  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                      底层 · 具体行动                         │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  每天：做一件“没有目标”的分享                           │  │</span></span>
<span class="line"><span>│  │  每次焦虑时：问自己“是事实需要，还是程序报警？”          │  │</span></span>
<span class="line"><span>│  │  每次见面：设定“零KPI”目标                              │  │</span></span>
<span class="line"><span>│  │  每次被善待：只说“谢谢，很开心”，不说“那我也……”          │  │</span></span>
<span class="line"><span>│  │  每周：回顾一次“什么都没发生但很舒服”的时刻              │  │</span></span>
<span class="line"><span>│  └───────────────────────────────────────────────────────┘  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><h3 id="顶层-思维转变" tabindex="-1">顶层 - 思维转变 <a class="header-anchor" href="#顶层-思维转变" aria-label="Permalink to &quot;顶层 - 思维转变&quot;">​</a></h3><p>这层是指导思想，是一种你想通之后自然做出来的</p><h4 id="从-我必须赚取爱-到-我本身就有资格被爱" tabindex="-1">从“我必须赚取爱”到“我本身就有资格被爱” <a class="header-anchor" href="#从-我必须赚取爱-到-我本身就有资格被爱" aria-label="Permalink to &quot;从“我必须赚取爱”到“我本身就有资格被爱”&quot;">​</a></h4><p>小时候，我们不是一个独立的人，不管是心理还是物质上，都必须依附父母才能存活。</p><p>而现在，我们已经不是那个孩子了，已经不需要向任何人证明我需要被爱</p><blockquote><p>试着对自己说这句话：“我什么都不做的时候，也值得被喜欢。”一开始可能不相信，甚至会质疑或者放弃，但说多了，你的大脑会慢慢接受这个设定</p><p>不要小瞧自我激励、自我暗示的力量</p></blockquote><h4 id="从-关系是任务清单-到-关系是共同土壤" tabindex="-1">从“关系是任务清单”到“关系是共同土壤” <a class="header-anchor" href="#从-关系是任务清单-到-关系是共同土壤" aria-label="Permalink to &quot;从“关系是任务清单”到“关系是共同土壤”&quot;">​</a></h4><p>任务清单思维是：陌生 -&gt; 认识 -&gt; 熟悉 -&gt; 亲密......每一步都要做对，错了就完蛋</p><p>土壤思维是：关系是一片土壤，我们在上面哭着、笑着、呆着、分享、沉默...这些都会让土壤变得更肥沃。</p><p>不需要每天“推进”，因为土壤会自己生长</p><blockquote><p>每次你想“我应该推进什么”的时候，不妨换成：</p><ul><li>“此刻我们在这片土壤里，舒服吗？”</li><li>“应该做什么，能更好的浇灌土壤？”</li></ul></blockquote><details class="details custom-block"><summary>另外：一个邪修方法</summary><ul><li>如果你是因为性别而不自在，那就把对方当做同性</li><li>如果你是因为关系而不自在，那就把对方当做熟悉的朋友</li><li>如果你是因为没话说觉得尴尬，那就直说“嗯..现在，我其实是想找些话题的，但是，显然脑子一片空白......”</li></ul><p>其本质，就是淡化对方在自己心中的位置，淡化对方对自己的影响，这样我们能更真实的展现自己</p></details><h3 id="中间层-认知习惯" tabindex="-1">中间层 - 认知习惯 <a class="header-anchor" href="#中间层-认知习惯" aria-label="Permalink to &quot;中间层 - 认知习惯&quot;">​</a></h3><p>这是每天的思考方式，经常练习，将其变成肌肉记忆，将其变成本能</p><h4 id="习惯一-区分-事实-与-旧程序" tabindex="-1">习惯一：区分“事实”与“旧程序” <a class="header-anchor" href="#习惯一-区分-事实-与-旧程序" aria-label="Permalink to &quot;习惯一：区分“事实”与“旧程序”&quot;">​</a></h4><p>当你感到焦虑、想进攻或撤退的时候，停下里问问自己：</p><ul><li>事实上，发生了什么事？（比如，对方俩三小时没有回复消息）</li><li>旧程序在告诉我什么？（比如，对方是不是故意不回的，ta是不是对我没兴趣）</li></ul><p>事实往往比旧程序温和多了，学会把这两者区分开来</p><p>有一项研究表明，让我们难过的往往不是事实本身，而是我们沉溺进了这件事带给我们的感受中去了，而且，越沉越深，越想越多</p><h4 id="习惯二-把-撤退-转化为-留白" tabindex="-1">习惯二：把“撤退”转化为“留白” <a class="header-anchor" href="#习惯二-把-撤退-转化为-留白" aria-label="Permalink to &quot;习惯二：把“撤退”转化为“留白”&quot;">​</a></h4><p>撤退是消失，是不联系，然后观察对方的反应。留白是不主动索取，不期待回应，但我依然在那里</p><blockquote><p>当你知道该不该联系时，发一张照片、一个表情、一句“刚看到这个想到你” —— 不追问，不期待回复。这就是留白。</p></blockquote><h4 id="习惯三-接受-无目的的给予" tabindex="-1">习惯三：接受“无目的的给予” <a class="header-anchor" href="#习惯三-接受-无目的的给予" aria-label="Permalink to &quot;习惯三：接受“无目的的给予”&quot;">​</a></h4><p>当别人对你好、主动联系你、或者只是安静陪着你时，练习不急着回报。你不需要立刻说“那下次我请你看电影”或者“你有什么需要我帮忙的”。</p><p>只需要说：“谢谢，我很开心。”然后允许自己只是接收，不付出。</p><p><strong>这对你来说可能非常难，因为你的程序告诉你“欠了就要还”</strong>。但真正的亲密关系里，爱不是债务。</p><h4 id="习惯四-用-渐进-替代-进攻" tabindex="-1">习惯四：用“渐进”替代“进攻” <a class="header-anchor" href="#习惯四-用-渐进-替代-进攻" aria-label="Permalink to &quot;习惯四：用“渐进”替代“进攻”&quot;">​</a></h4><p>“进攻”是一步到位，带着“必须成功”的压力。“渐进”是每次只走一小步，允许后退，不设定终点。</p><p>比如，在一次约会中，你的目标不是“今晚必须牵手”、“这次必须有关系推进”，而是“今晚可以做一次轻微的靠近，然后看她是否也向我靠近”。</p><h3 id="底层-具体行动" tabindex="-1">底层 - 具体行动 <a class="header-anchor" href="#底层-具体行动" aria-label="Permalink to &quot;底层 - 具体行动&quot;">​</a></h3><p>这些是你每天、每周可以直接做的事。从最容易的开始，一个一个来。</p><h4 id="行动一-每天做一件-没有目标-的分享" tabindex="-1">行动一：每天做一件“没有目标”的分享 <a class="header-anchor" href="#行动一-每天做一件-没有目标-的分享" aria-label="Permalink to &quot;行动一：每天做一件“没有目标”的分享&quot;">​</a></h4><p>拍一张路边的花，发给朋友，只写：“今天的偶遇”</p><p>或者不发给任何人，只是发在只有自己看得到的地方，练习“分享本身就是目的”。</p><h4 id="行动二-每次焦虑时-问自己那个问题" tabindex="-1">行动二：每次焦虑时，问自己那个问题 <a class="header-anchor" href="#行动二-每次焦虑时-问自己那个问题" aria-label="Permalink to &quot;行动二：每次焦虑时，问自己那个问题&quot;">​</a></h4><p>把这个问题写在手机备忘录里，或者设成屏保：</p><p>“是事实需要，还是旧程序报警？”</p><p>每次你想“我该做什么”的时候，先看一遍这个问题，再决定。</p><h4 id="行动三-每次见面-设定-零kpi-目标" tabindex="-1">行动三：每次见面，设定“零KPI”目标 <a class="header-anchor" href="#行动三-每次见面-设定-零kpi-目标" aria-label="Permalink to &quot;行动三：每次见面，设定“零KPI”目标&quot;">​</a></h4><p>见面之前，对自己说：“今天的唯一目标是 —— 我们都舒服。不管有没有牵手，不管有没有推进关系，只要两个人都觉得舒服，就算成功。”</p><h4 id="行动四-每次被善待-只说-谢谢-和感受" tabindex="-1">行动四：每次被善待，只说“谢谢”和感受 <a class="header-anchor" href="#行动四-每次被善待-只说-谢谢-和感受" aria-label="Permalink to &quot;行动四：每次被善待，只说“谢谢”和感受&quot;">​</a></h4><p>下次她主动找你聊天、送你小东西、或者只是陪你安静坐着时，忍住你想“回报”的冲动。只说：“谢谢，我很开心。”然后看看会发生什么。</p><h4 id="行动五-每周回顾一次-什么都没发生-的时刻" tabindex="-1">行动五：每周回顾一次“什么都没发生”的时刻 <a class="header-anchor" href="#行动五-每周回顾一次-什么都没发生-的时刻" aria-label="Permalink to &quot;行动五：每周回顾一次“什么都没发生”的时刻&quot;">​</a></h4><p>每周日晚上，花两分钟回想这一周里，有没有哪一刻是你什么都没做、什么都没推进，但觉得“这样也挺好”的？记下来。哪怕只有一次，也说明你在进步。</p><h2 id="最后要说的" tabindex="-1">最后要说的 <a class="header-anchor" href="#最后要说的" aria-label="Permalink to &quot;最后要说的&quot;">​</a></h2><p>最难的部分，其实就是看清自己，而我们已经走完这一步了，这已经证明，我们已经不是那个需要表现才被爱的孩子了</p><p>而改变自己，俗话说江山易改本性难移，转换思维会很困难，期间也一定会遇到挫折，甚至一度想要放弃</p><p>这种情况很正常的，改变是一步一步的，如果想放弃说明我们步子可能跨得太大了，不妨停下来几天，静静呆着，或者思索自己，会走的更远</p><p>真正的勇敢，是明知道做这件事情会很困难，甚至不知道是否有成功的那天，但我们依旧选择走在路上，洗把脸，重新出发</p><p>另外：人的任何行为，都能反应出他的思维，思维决定行为，常常关注自己面对事物的反应，能帮我们更好的了解自己</p>`,78)])])}const d=s(l,[["render",r]]);export{u as __pageData,d as default};
